INCLUDE PERFETTO MODULE slices.with_context;
CREATE PERFETTO TABLE analysis_mb AS
 SELECT row_number() OVER(ORDER BY ts) mb,id,ts,dur,ts+dur end_ts FROM thread_slice
 WHERE category='user_annotation' AND name GLOB 'task.profile_update.*.microbatch.rank0';
CREATE PERFETTO TABLE analysis_windows AS
 WITH bounds AS (SELECT (SELECT min(ts) FROM thread_slice WHERE category='user_annotation' AND name GLOB 'task.profile_update.*.train_step.rank0') t0,
 (SELECT ts FROM analysis_mb WHERE mb=1) f0,(SELECT end_ts FROM analysis_mb WHERE mb=3) f3)
 SELECT 'input' win,t0 lo,f0 hi FROM bounds UNION ALL SELECT 'three_fb',f0,f3 FROM bounds UNION ALL SELECT 'input_plus_three_fb',t0,f3 FROM bounds
 UNION ALL SELECT 'mb'||mb,ts,end_ts FROM analysis_mb WHERE mb<=3;
CREATE PERFETTO TABLE analysis_device AS
 SELECT *, CASE WHEN category='gpu_memcpy' THEN 'copy' WHEN category='gpu_memset' THEN 'memset'
 WHEN lower(name) GLOB '*nccl*' THEN 'nccl' WHEN name GLOB '*ag_nvl*' OR name GLOB '*rs_nvl*' OR lower(name) GLOB '*deep_ep*' OR lower(name) GLOB '*deepep*' THEN 'ep'
 ELSE 'other_kernel' END family FROM thread_slice WHERE category IN ('kernel','gpu_memcpy','gpu_memset');
SELECT win,round((hi-lo)/1e6,6) ms FROM analysis_windows;

