DROP TABLE analysis_device;
CREATE PERFETTO TABLE analysis_device AS
 SELECT *, CASE WHEN category='gpu_memcpy' THEN 'copy' WHEN category='gpu_memset' THEN 'memset'
 WHEN lower(name) GLOB '*nccl*' THEN 'nccl' WHEN name GLOB '*hybrid_ep::*' OR name GLOB '*ag_nvl*' OR name GLOB '*rs_nvl*' OR lower(name) GLOB '*deep_ep*' OR lower(name) GLOB '*deepep*' THEN 'ep'
 ELSE 'other_kernel' END family FROM thread_slice WHERE category IN ('kernel','gpu_memcpy','gpu_memset');
CREATE PERFETTO TABLE analysis_clipped AS
 SELECT w.win,d.id,d.category,d.name,d.family,MAX(d.ts,w.lo) b,MIN(d.ts+d.dur,w.hi) e
 FROM analysis_device d JOIN analysis_windows w ON d.ts<w.hi AND d.ts+d.dur>w.lo;
CREATE PERFETTO TABLE analysis_union AS
 WITH expanded AS (SELECT * FROM analysis_clipped UNION ALL SELECT win,id,category,name,'all_device',b,e FROM analysis_clipped),
 prev AS (SELECT *,MAX(e) OVER(PARTITION BY win,family ORDER BY b,e,id ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING) previous_end FROM expanded)
 SELECT win,family,count(*) n,sum(e-b)/1e6 sum_ms,sum(MAX(0,e-MAX(b,coalesce(previous_end,b))))/1e6 union_ms,max(e-b)/1e6 max_ms FROM prev GROUP BY win,family;
SELECT win,family,n,round(sum_ms,3) sum_ms,round(union_ms,3) union_ms,round(max_ms,3) max_ms FROM analysis_union
WHERE win IN ('input','three_fb') ORDER BY win,family;

